import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const root = new URL('../apps/api/prisma/', import.meta.url);
const source = readFileSync(new URL('schema.prisma', root), 'utf8').replaceAll('\r\n', '\n');
const generated =
  '// Generated by pnpm db:postgres:sync; edit prisma/schema.prisma first.\n' +
  source.replace('provider = "sqlite"', 'provider = "postgresql"');
const target = new URL('postgresql/schema.prisma', root);
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8').replaceAll('\r\n', '\n') !== generated)
    throw new Error('PostgreSQL 模型未同步，请执行 pnpm db:postgres:sync 并检查迁移');
} else {
  mkdirSync(new URL('postgresql/', root), { recursive: true });
  writeFileSync(target, generated);
}
